css:
[data-environment-identification="pill"]{display:none !important}
:root{--ns-dot:max(4px,calc(100vh / 180),calc(100cqw / 320))}
[data-chat-column]{position:relative;container-type:inline-size;isolation:isolate}
[data-chat-column]::before,[data-chat-column]:not(:has(.messages-timeline-scroll))::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none}
[data-chat-column]::before{image-rendering:pixelated}
[data-chat-column]:not(:has(.messages-timeline-scroll))::after{animation:ns-twinkle 5.5s ease-in-out infinite alternate}
@keyframes ns-twinkle{from{opacity:.2}to{opacity:.85}}
@media (prefers-reduced-motion:reduce){[data-chat-column]:not(:has(.messages-timeline-scroll))::after{animation:none;opacity:.5}}
[data-chat-header],[data-workspace-area="conversation"]{background-color:transparent !important}
[data-chat-header]{image-rendering:pixelated}
[data-chat-header] > *{image-rendering:auto}
[data-slot="composer-context-strip"]{background:transparent !important;-webkit-backdrop-filter:none !important;backdrop-filter:none !important;box-shadow:none !important;border:0 !important}
[data-slot="sidebar"] a[aria-label="T3 Code home"]{color:#fff !important}
[data-slot="sidebar"] a[aria-label="T3 Code home"] span span{color:rgba(255,255,255,.7) !important}
:is([data-slot="sidebar"] button[aria-label="Go back"],[data-slot="sidebar"] button[aria-label="Go forward"],[data-slot="sidebar"] button[aria-label="Toggle main sidebar"]){color:rgba(255,255,255,.9) !important}
:is([data-slot="sidebar"] button[aria-label="Go back"],[data-slot="sidebar"] button[aria-label="Go forward"],[data-slot="sidebar"] button[aria-label="Toggle main sidebar"]):hover{background:rgba(255,255,255,.1) !important;color:#fff !important}
[data-chat-composer-form] button[class~="bg-message-action"]:hover{filter:brightness(1.1)}
[data-chat-composer-form] button[class~="bg-message-action"]:disabled{opacity:.64;color:#fff !important}
